	const uint32_t i1 = inc[1];
	uint32_t g0 = g[0];
	uint32_t g1 = g[1];
	const int32_t d0 = dg[0];
	const int32_t d1 = dg[1];
	uint32_t p0 = phase[0];
	uint32_t p1 = phase[1];
